  totalTasks: number;
  byStatus: Record<'pending' | 'running' | 'completed', number>;
  // ... other fields
}

async function generateSummary(): Promise<Summary> {
  const tasks = await loadTasks();
  const byStatus = tasks.reduce((acc, t) => { acc[t.status] = (acc[t.status] || 0) + 1; return acc; }, {} as Record<string, number>);
  // Similar reductions for priority, tags, averages
  return { totalTasks: tasks.length, byStatus, /* ... */ };
}

