  .description('Run a task with gate summary')
  .option('--id <id>', 'Task ID')
  .option('--max-pending <num>', 'Max pending tasks allowed', 10)
  .action(async (options) => {
    const summary = await generateSummary();
    console.log('Pre-execution Summary:', JSON.stringify(summary, null, 2));
